/// Call media type, used to specify whether to initiate an audio call or video call.
enum CallMediaType {
  /// Audio call.
  audio(1),

  /// Video call.
  video(2);

  const CallMediaType(this.value);
  final int value;
}

/// Call end reason, used to identify how the audio/video call ended (normal hangup, rejection, timeout, etc.).
///
/// This enum describes the various reasons why a call ended, helping developers understand how the call was terminated.
///
/// ### End Reason Description
///
/// | Reason | Description | Typical Scenario |
/// |------|-----------|----------------|
/// | `unknown` | Unknown reason | Unable to determine the end reason |
/// | `hangup` | Normal hangup | User actively hangs up the call |
/// | `reject` | Rejected | Callee rejects the incoming call |
/// | `noResponse` | No response | Callee did not answer within timeout |
/// | `offline` | Offline | Callee is offline |
/// | `lineBusy` | Line busy | Callee is already in a call |
/// | `canceled` | Canceled | Caller cancels before callee answers |
/// | `otherDeviceAccepted` | Accepted on another device | The call was picked up on another device associated with the same account. |
/// | `otherDeviceReject` | Rejected on another device | Call was rejected on another logged-in device |
/// | `endByServer` | Ended by server | Call was terminated by the server |
enum CallEndReason {
  /// Unknown reason.
  unknown(0),

  /// Normal hangup.
  hangup(1),

  /// Rejected.
  reject(2),

  /// No response.
  noResponse(3),

  /// Offline.
  offline(4),

  /// Line busy.
  lineBusy(5),

  /// Call was canceled.
  canceled(6),

  /// Accepted on another device.
  otherDeviceAccepted(7),

  /// Rejected on another device.
  otherDeviceReject(8),

  /// Call ended by backend.
  endByServer(9);

  const CallEndReason(this.value);
  final int value;
}

/// Call direction, used to identify whether the call is incoming, outgoing, or missed.
enum CallDirection {
  /// Unknown.
  unknown(0),

  /// Missed call.
  missed(1),

  /// Incoming call.
  incoming(2),

  /// Outgoing call.
  outgoing(3);

  const CallDirection(this.value);
  final int value;
}

/// Call participant status, used to identify whether the participant is waiting or has answered.
enum CallParticipantStatus {
  /// No status (not in call).
  none(0),

  /// Waiting (calling/being called).
  waiting(1),

  /// Accepted.
  accept(2);

  const CallParticipantStatus(this.value);
  final int value;
}

/// Cloud recording policy for audio/video calls, used to configure whether to enable cloud recording for a specific call.
///
/// This enum defines the cloud recording policy for a call session, allowing you to follow the console configuration or override it.
///
/// ### Policy Options
///
/// | Policy | Description |
/// |------|-----------|
/// | `followConsoleConfig` | Follow the global configuration in the console |
/// | `enable` | Enable cloud recording | overriding the console configuration |
/// | `disable` | Disable cloud recording | overriding the console configuration |
enum CloudRecordPolicy {
  /// Follow the global configuration in the console (default).
  followConsoleConfig(0),

  /// Enable cloud recording, overriding the console configuration.
  enable(1),

  /// Disable cloud recording, overriding the console configuration.
  disable(2);

  const CloudRecordPolicy(this.value);
  final int value;
}

/// Call parameter configuration, used to set room ID, timeout, custom data, and other parameters when initiating an audio/video call.
///
/// Configuration parameters for initiating audio/video calls, including room ID, timeout, custom data, etc.
class CallParams {
  /// TRTC room ID (CallStore's media stream management uses Tencent Cloud TRTC service). Optional parameter.
  /// When not provided, it is automatically generated by the server; if your app needs to specify or reuse a TRTC room, you can pass in a specific string.
  String roomId;

  /// Ring timeout duration (seconds). Optional parameter.
  /// Only controls the unanswered timeout phase from call initiation (`calls`) to answer. Does not apply to already connected calls or `invite` operations.
  /// When set to 0, the server default (30s) will be used.
  int timeout;

  /// Custom pass-through data attached when making a call. Optional parameter.
  /// This data is primarily exposed to the callee's business logic via the `onCallReceived` event.
  /// @note It does not enter the long-term `CallInfo` state, nor is it persisted to call records. It is recommended to pass a short JSON string.
  String userData;

  /// Tencent Cloud IM group ID. Optional parameter.
  /// Only needs to be provided in the "call initiated from a group chat" scenario. When provided, the system will route signaling and associate this call with the group's call records, for sending call start/end status messages in the group chat and for inviting group members to join the call during the call.
  /// For one-on-one calls, or ad-hoc multi-party calls not bound to a specific group, always leave this empty.
  /// @note This field takes effect on the initial `calls` invocation; subsequent `invite` parameters cannot change the group bound to this call.
  String chatGroupId;

  /// Ephemeral call. Optional parameter.
  /// When set to `true`, no call message will be generated after this call ends. Common scenario: initiating a call in a 1v1 chat without displaying the call message.
  bool isEphemeralCall;

  /// Cloud recording policy for this call. Prerequisite: the relevant capability must already be enabled in the console.
  /// - followConsoleConfig (default): Follow the global configuration in the console.
  /// - enable: Force-enable cloud recording, overriding the global configuration in the console.
  /// - disable: Force-disable cloud recording, overriding the global configuration in the console.
  CloudRecordPolicy cloudRecordPolicy;

  /// Offline push notification title.
  /// When not empty, overrides the default title (login user's nickname).
  String offlinePushTitle;

  /// Offline push notification description.
  /// When not empty, overrides the default description.
  String offlinePushDescription;

  CallParams({
    this.roomId = "",
    this.timeout = 30,
    this.userData = "",
    this.chatGroupId = "",
    this.isEphemeralCall = false,
    this.cloudRecordPolicy = CloudRecordPolicy.followConsoleConfig,
    this.offlinePushTitle = "",
    this.offlinePushDescription = "",
  });
}

/// Call participant information, including user ID, nickname, avatar, participation status, microphone/camera on/off status, etc.
///
/// Contains complete information about a call participant including user ID, nickname, avatar, participation status, and device states.
class CallParticipantInfo {
  /// User ID.
  final String id;

  /// User nickname.
  final String name;

  /// User avatar URL.
  final String avatarURL;

  /// Friend remark.
  final String remark;

  /// Participant status.
  final CallParticipantStatus status;

  /// Whether microphone is on.
  final bool isMicrophoneOpened;

  /// Whether camera is on.
  final bool isCameraOpened;

  CallParticipantInfo._({
    this.id = "",
    this.name = "",
    this.avatarURL = "",
    this.remark = "",
    this.status = CallParticipantStatus.none,
    this.isMicrophoneOpened = false,
    this.isCameraOpened = false,
  });
}

/// Call information, including call ID, room ID, initiator, invitees, media type, call direction, start time, duration, and other complete information.
///
/// Contains complete information about a call session including call ID, room ID, initiator, invitees, media type, direction, timing, and duration.
class CallInfo {
  /// Call ID.
  final String callId;

  /// Room ID.
  final String roomId;

  /// Initiator ID.
  final String inviterId;

  /// Invitee ID list.
  final List<String> inviteeIds;

  /// Chat group ID.
  final String chatGroupId;

  /// Call media type.
  /// @note May be null (null / nil) during early event stages, when the type is unknown, or when historical call records (recent calls) have not fully back-filled this field. Handle optional unwrapping accordingly.
  final CallMediaType? mediaType;

  /// Call direction / record type (e.g., incoming, outgoing, missed).
  /// @note This does not represent the specific reason for call termination. For end reasons, refer to the `CallEndReason` enum.
  final CallDirection result;

  /// Timestamp of when the call was actually connected (unit: milliseconds).
  final int startTime;

  /// Call duration (seconds).
  final int duration;

  CallInfo._({
    this.callId = "",
    this.roomId = "",
    this.inviterId = "",
    this.inviteeIds = const [],
    this.chatGroupId = "",
    this.mediaType,
    this.result = CallDirection.unknown,
    this.startTime = 0,
    this.duration = 0,
  });
}

/// Call state data, manages the real-time data state of the current call.
///
/// A comprehensive snapshot of the current call session state. This structure contains all relevant information about active calls, recent call records, participant lists, etc.
///
/// > **Note**: Call state updates automatically. Subscribe to `state` to receive real-time updates.
///
/// ### State Properties Overview
///
/// | Property | Type | Description |
/// |--------|------|-----------|
/// | `activeCall` | `ValueListenable<CallInfo>` | Current active call information |
/// | `recentCalls` | `ValueListenable<List<CallInfo>>` | Recent call records list |
/// | `cursor` | `ValueListenable<String>` | Pagination cursor |
/// | `selfInfo` | `ValueListenable<CallParticipantInfo>` | Current user's own information |
/// | `allParticipants` | `ValueListenable<List<CallParticipantInfo>>` | All participants in current call |
/// | `speakerVolumes` | `ValueListenable<Map<String, int>>` | Participant volume information |
/// | `networkQualities` | `ValueListenable<Map<String, NetworkQuality>>` | Participant network quality information |
abstract class CallState {
  /// Current active call information.
  /// **Lifecycle Contract**: When `onCallEnded` is triggered, this object is not immediately cleared; instead, it retains the call's final state for the UI to display end animations (at this point `CallInfo.result` or other parameters reflect the end reason). If a new call is initiated or received, it will be automatically overwritten. Developers can manually clean up by resetting the related `CallStore` state.
  ValueListenable<CallInfo> get activeCall;

  /// Recent call records list.
  /// @note Each call to `queryRecentCalls` currently behaves as an **overwrite update** rather than an automatic append. To implement infinite scrolling, the business layer needs to concatenate newly arrived data with the existing list on its own.
  ValueListenable<List<CallInfo>> get recentCalls;

  /// Pagination cursor, used to query more call records.
  ValueListenable<String> get cursor;

  /// Current user's own information.
  ValueListenable<CallParticipantInfo> get selfInfo;

  /// All participants in current call.
  ValueListenable<List<CallParticipantInfo>> get allParticipants;

  /// Participant volume information, key is user ID, value is volume level.
  ValueListenable<Map<String, int>> get speakerVolumes;

  /// Participant network quality information, key is user ID, value is network quality.
  ValueListenable<Map<String, NetworkQuality>> get networkQualities;

  /// @nodoc
  ValueNotifier<double> get zoom;
}

/// Call events, used to receive various event notifications during a call.
class CallEventListener {
  /// Callback when a call event starts.
  /// Timing Note: This indicates that "the current call flow has been successfully entered (e.g., `calls` was initiated and accepted internally)," but **it does not mean the audio/video room has been connected or established**. It is recommended to use this only for the initial UI navigation (on the caller side).
  /// - [callId] : Call ID.
  /// - [mediaType] : Call media type.
  void Function(String callId, CallMediaType mediaType)? onCallStarted;

  /// Callback when a new call invitation is received.
  /// Field Reading Recommendation: The event parameters only pass through `callId`, `mediaType`, and `userData`. If you need to read the full information such as the inviter, room ID, or associated group ID, please read it from `state.activeCall` after receiving this event.
  /// - [callId] : Call ID.
  /// - [mediaType] : Call media type.
  /// - [userData] : Custom data passed by the caller (typically a JSON-formatted string).
  void Function(String callId, CallMediaType mediaType, String userData)? onCallReceived;

  /// Unified callback for call ending events.
  /// Multi-scenario Note: Whether it's a hangup after connection, a no-answer timeout, cancellation by the remote side, or the call being answered on another device, this event will ultimately be triggered. Developers must check the `reason` parameter to determine the specific cause and display the corresponding UI text or handle branching logic.
  /// Getting Call Duration: This event's parameters do not include a call duration field. To get the call duration, read `state.activeCall.duration` when this callback is received (unit: seconds). After the call is connected, the SDK internally increments this value every second; when the call ends, `activeCall` is not immediately cleared, so it can be safely read within this callback.
  /// - [callId] : Call ID.
  /// - [mediaType] : Call media type.
  /// - [reason] : Call end reason.
  /// - [userId] : User ID who triggered the end.
  void Function(String callId, CallMediaType mediaType, CallEndReason reason, String userId)? onCallEnded;

  CallEventListener({
    this.onCallStarted,
    this.onCallReceived,
    this.onCallEnded,
  });
}

/// Audio/video call management APIs for initiating, answering, rejecting, hanging up calls, group call management, and call history management.
///
/// `CallStore` Manages all audio/video call related operations.
/// Including initiating, answering, rejecting, hanging up, group call management, and call history management.
/// Audio/video call functionality is implemented through `CallStore` for real-time audio/video interaction between users. `CallStore` provides a comprehensive set of APIs to manage the entire call lifecycle.
///
/// When integrating `CallStore`, please be aware of the following runtime characteristics:
/// - **Error Handling**: When actively calling an API (e.g., `calls`), if the call itself fails due to parameter validation or state conflicts, you will typically be notified via an asynchronously thrown error event or a returned error code. Network or remote-side anomalies are also delivered through `onCallEnded` with the error reason attached.
/// - **Threading Model & Cleanup**: All state updates (`CallState`) and event callbacks (`CallEvent` / `CallEventListener`) are typically **guaranteed to fire on the main thread**, so they can be used directly to refresh the UI. Under the global singleton pattern, be sure to unregister listeners when components are destroyed (e.g., `deinit` / `onDestroy`) to avoid memory leaks.
///
/// ### Key Features
///
/// - **Create Audio/Video Calls**：Support initiating audio or video calls to one or multiple users, with configurable timeout, custom data, and other parameters.
/// - **Answer/Reject Audio/Video Calls**：When receiving an incoming call invitation, you can choose to answer or reject.
/// - **Hang Up Audio/Video Calls**：End the current ongoing audio/video call.
/// - **Group Call Management**：Support joining existing group calls or inviting other users to join during a call.
/// - **Call History Management**：Query recent call records (with pagination support), delete specified call records.
/// - **Event-Driven Architecture**：Provides event listeners for call started, call received, call ended, etc.
/// - **State Subscription**：Real-time subscription to current call state, including participant list, volume information, network quality, etc.
///
/// > **Important**: Ensure the SDK is initialized before accessing the `CallStore.shared` singleton. Do not instantiate it directly, as doing so will prevent you from receiving call state updates.
///
/// > **Note**: Call state updates are delivered through the `state` publisher. Subscribe to it to receive real-time updates of call data.
///
/// ### Call Operations Overview
///
/// The following table shows the main call operations.
///
/// | Feature | Method | Description |
/// |-------|------|-----------|
/// | Create Call | `calls` | Create an audio or video call to specified users |
/// | Answer Call | `accept` | Answer an incoming call |
/// | Reject Call | `reject` | Reject an incoming call |
/// | Hang Up Call | `hangup` | Hang up the current call |
/// | Join Call | `join` | Actively join a group call |
/// | Invite Users | `invite` | Invite other users to join the current call |
///
/// ### Call History Management
///
/// | Feature | Method | Description |
/// |-------|------|-----------|
/// | Query Records | `queryRecentCalls` | Query recent call records (with pagination support) |
/// | Delete Records | `deleteRecentCalls` | Delete specified call records |
///
/// ### Usage Example
///
/// ```dart
/// import 'package:atomic_x_core/atomicxcore.dart';
///
/// // Create a video call
/// final result = await CallStore.shared.calls(
///   ["mike"],
///   CallMediaType.video,
///   null,
/// );
/// ```
///
/// ## Topics
///
/// ### Get Instance
/// - [shared] : Get the CallStore singleton instance.
///
/// ### Observe State and Events
/// - [state] : Reactive state containing active call, participant list, volume information, and network quality.
/// - [addListener]/[removeListener] : Call event callbacks.
///
/// ### Call Operations
/// - [calls] : Create a call.
/// - [accept] : Answer a call.
/// - [reject] : Reject a call.
/// - [hangup] : Hang up a call.
/// - [join] : Join a group call.
/// - [invite] : Invite users to join a call.
///
/// ### Call History
/// - [queryRecentCalls] : Query recent call records.
/// - [deleteRecentCalls] : Delete call records.
///
/// ## See Also
///
/// - [CallMediaType]
/// - [CallEndReason]
/// - [CallDirection]
/// - [CallParticipantStatus]
/// - [CallParams]
/// - [CloudRecordPolicy]
/// - [CallParticipantInfo]
/// - [CallInfo]
/// - [CallState]
/// - [CallEventListener]
abstract class CallStore {
  /// CallStore singleton instance.
  static final CallStore _instance = _CallStoreImpl();

  static CallStore get shared => _instance;

  /// Current call state, including active call, participant list, volume information, network quality, etc.
  CallState get state;

  /// Create an audio or video call to specified users, supporting both one-on-one and group calls.
  ///
  /// - [participantIds] : List of callee IDs, supports single or multiple users.
  /// - [mediaType] : Call media type (audio/video).
  /// - [params] : Call parameter configuration.
  Future<CompletionHandler> calls(List<String> participantIds, CallMediaType mediaType, CallParams? params);

  /// Answer a call. Call this method to answer the call when receiving an incoming call invitation.
  ///
  Future<CompletionHandler> accept();

  /// Reject a call. Call this method to reject the call when receiving an incoming call invitation.
  ///
  Future<CompletionHandler> reject();

  /// Hang up and end the current ongoing call.
  ///
  Future<CompletionHandler> hangup();

  /// Join an ongoing group call using a specific call ID.
  ///
  /// - [callId] : Call ID to join.
  Future<CompletionHandler> join(String callId);

  /// Invite other users to join during an ongoing call.
  ///
  /// - [participantIds] : List of invitee IDs.
  /// - [params] : Call parameter configuration.
  Future<CompletionHandler> invite(List<String> participantIds, CallParams? params);

  /// Query recent call records.
  /// **Current Limitation**: Currently, query results **overwrite (reset)** the `state.recentCalls` list each time, rather than automatically appending.
  ///
  /// - [cursor] : Pagination cursor, pass empty string for first query.
  /// - [count] : Query count.
  Future<CompletionHandler> queryRecentCalls(String cursor, int count);

  /// Delete specified call records.
  ///
  /// - [callIdList] : List of call IDs to delete.
  Future<CompletionHandler> deleteRecentCalls(List<String> callIdList);

  /// Call experimental API
  ///
  /// - [jsonMap] : JSON parameter map.
  /// - [callback] : Called with the error code, message and the JSON string returned by the engine when the invocation completes.
  Future<void> callExperimentalAPI(Map<String, dynamic> jsonMap, {ExperimentalAPICallback? callback});

  /// Subscribe to experimental event
  ///
  /// - [event] : Event name.
  /// - [callback] : Event callback delivering (roomID, jsonStr).
  ///
  /// Returns: Subscription token for unsubscribing.
  SubscriptionToken subscribeExperimentalEvent(String event, ExperimentalEventCallback callback);

  /// Unsubscribe from experimental event
  ///
  /// - [token] : Subscription token.
  void unsubscribeExperimentalEvent(SubscriptionToken token);

  /// Add call event callback listener
  ///
  /// - [listener] : Listener.
  void addListener(CallEventListener listener);

  /// Remove call event callback listener
  ///
  /// - [listener] : Listener.
  void removeListener(CallEventListener listener);
}
